        return None
    if isinstance(s,str) and s.endswith('Z'):
        s2 = s[:-1] + '+00:00'
    else:
        s2 = s
    try:
        return datetime.fromisoformat(s2)
    except Exception:
        try:
            return datetime.strptime(s2, '%Y-%m-%dT%H:%M:%S')
        except Exception:
